"""Write the source-bound power rework review after the checks finish."""
import hashlib,html,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'dist/power-fix-2026-10-27'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
board=OUT/'verified-final.circuit.json';digest=sha(board)
for name,source in {'validation.json':'dist/validation/board.json','core-dc.json':'dist/power-distribution/dc-audit.json','slot-dc.json':'dist/slot-power-routing/dc-audit.json','5v-dc.json':'dist/atx5v-routing/dc-audit.json','3v3-dc.json':'dist/vcch-routing/dc-audit.json','margins.json':'dist/schematic-review/margins.json','datasheets.json':'dist/schematic-review/datasheet-check.json','reset.json':'dist/power-reset/report.json','heatsink.json':'dist/heatsink-fit/results.json'}.items():
 p=ROOT/source;obj=read(p)
 if 'sourceSha256' in obj:assert obj['sourceSha256']==digest,(source,'stale')
 shutil.copyfile(p,OUT/name)
validation,core,slot,five,three,margins,dynamics=[read(OUT/n) for n in ['validation.json','core-dc.json','slot-dc.json','5v-dc.json','3v3-dc.json','margins.json','power/results.json']]
assert validation['passed'] and three['passed'] and five['passed']
assert dynamics['sourceSha256']==digest and all(c['passed'] for c in dynamics['numericChecks']) and read(OUT/'power/spice-check.json')['passed']
preserve=read(OUT/'preservation.json');assert preserve['sourceSha256']==digest and preserve['passed'] and not preserve['changedPriorParts'] and not preserve['changedPriorRoutes']
external=read(OUT/'bridge-and-external-dc.json');assert external['sourceSha256']==digest and external['passed']
planned=read(ROOT/'simulations/power-dynamics/provisional-loads.json')['rails'];rails=[]
for r in core['results']:
 current=planned[r['rail']]['designCurrentA'];loss=r['screeningUpperDropMV']*current/r['currentA']
 rails.append(dict(rail=r['rail'],currentA=current,upperCopperLossMV=loss,limitMV=8,passed=loss<=8))
assert all(r['passed'] for r in rails)
c=next(c for c in slot['channels'] if c['rail']=='12V');loss=c['conductorUpperDropMV']+c['mosfetDrop25CMaxRdsMV']
twelve={**c,'totalColdFetLossMV':loss,'voltageFrom11p2VInput':11.2-loss/1000,'floorV':11.04,'marginMV':160-loss,'marginAt2xFetResistanceSensitivityMV':160-loss-c['mosfetDrop25CMaxRdsMV'],'hardwareQualified':False}
assert twelve['marginMV']>0
vdd=next(s for s in dynamics['summary'] if s['rail']=='VDD');examples=vdd['halfLoadStepExample'];low=min(c['lowToleranceMinimumV'] for c in examples)-vdd['worstRippleTroughMV']/1000;high=max(c['highToleranceMaximumV'] for c in examples)+vdd['worstRipplePeakMV']/1000
conditional=dict(currentStepA=1.5,loadEdgeNS=200,assumedCurrentResponseDelayUS=.5,assumedLinkNH=5,assumedReserveBranchNH=5,lowV=low,highV=high,limitsV=[1.1,1.16],passed=low>=1.1 and high<=1.16,closedLoopValidated=False)
assert conditional['passed']
reset=read(OUT/'reset.json');assert not reset['normalStartupEnvelope']['failedCases']
tests=(OUT/'tests-final.log').read_text();assert '173 pass' in tests and '0 fail' in tests
assert not read(OUT/'datasheets.json')['errors'] and not read(OUT/'datasheets.json')['missingBOMSourceEntries']
paths=['index.circuit.tsx','components/BuckInputs.tsx','components/VddReserve.tsx','imports/VddPrecisionFeedback.tsx','imports/CL05B473KO5NNNC.tsx','imports/T520B337M2R5ATE009.tsx','lib/vdd-reserve-routing.tsx','lib/vdd-reserve-spec.mjs','lib/pcb-group-placement.ts','lib/slot-power-routing.tsx','manufacturing/control-routing/component-rework.json','manufacturing/power-distribution/cost-reduction-copper.json','manufacturing/power-distribution/surface-si-moats.json','manufacturing/slot-power-routing/regions.json','manufacturing/stackup/selected.json','simulations/power-dynamics/run_review.py','simulations/power-dynamics/damped_bank.py','simulations/power-dynamics/prepare_current.mjs','simulations/power-distribution/check_dc.py','simulations/power-distribution/check_ground_returns.py','simulations/power-reset/scenarios.ts','tests/audits/schematic-audit.mjs','tests/audits/buck-routing-audit.ts','scripts/render-power-fix-review.py']
report=dict(dateLocal='2026-10-27',sourceFile=str(board.relative_to(ROOT)),sourceSha256=digest,stackupCode=slot['stackupCode'],status='DC and selected conditional first-response screens pass; full qualification remains open',hardwareQualified=False,corePlannedLoads=rails,slot12V=twelve,slot3V3=three['summary'],vddConditionalExample=conditional,startup=margins['startup'],normalStartupEnvelope=reset['normalStartupEnvelope'],preservation=preserve,tests=dict(passed=173,skipped=8,failed=0),inputSha256={p:sha(ROOT/p) for p in paths},openItems=['VDD controller response and interconnect inductance remain unvalidated. The retained 3 A-step, long-delay, high-inductance and degraded-ESR sensitivity cases still include failures.','The separate VCCL 3 A / 8 mV stress target remains open; the agreed 1 A load passes.','Slot ground-return, mating contacts, cable loss and guaranteed hot FET resistance remain outside the DC model.','The discrete 3.3 V slot-switch hot/restart SOA sensitivity still has cases outside its equivalent-pulse screen.',
'The existing reset RC does not monitor all rail faults; the retained late/missing-rail and brownout cases remain open.','Component sourcing, assembler process acceptance and a fresh delivered quote remain open. No hardware qualification or purchase is implied.'])

if three['summary']['slotMarginWith2xFetResistanceSensitivityMV']<0:
    report['openItems'].append(f"The 3.3 V doubled-FET-resistance sensitivity is below its floor by {-three['summary']['slotMarginWith2xFetResistanceSensitivityMV']:.3f} mV. This is a sensitivity case, not a guaranteed hot-resistance bound.")
(OUT/'review.json').write_text(json.dumps(report,indent=2)+'\n');(ROOT/'manufacturing/power-fix-review-2026-10-27.json').write_text(json.dumps(report,indent=2)+'\n')
rows=''.join(f'<tr><td>{r["rail"]}</td><td>{r["currentA"]:g} A</td><td>{r["upperCopperLossMV"]:.3f} mV</td><td>Below 8 mV</td></tr>' for r in rails)
rows+=''.join(f'<tr><td>5 V input to {r["rail"]}</td><td>{r["inputCurrentA"]:g} A</td><td>{r["withMeshAllowanceMV"]:.2f} mV</td><td>Below 100 mV</td></tr>' for r in five['results'])
issues=''.join('<li>'+html.escape(s)+'</li>' for s in report['openItems'])
(OUT/'report.html').write_text(f'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Flamingo power rework</title><style>body{{font:17px/1.55 system-ui;max-width:1000px;margin:40px auto;padding:0 24px;color:#182a34}}table{{border-collapse:collapse;width:100%}}th,td{{text-align:left;padding:10px;border-bottom:1px solid #ccd6d9}}.open{{background:#fff0d3;padding:16px;border-left:5px solid #b5791e}}img{{max-width:100%}}code{{overflow-wrap:anywhere}}a{{color:#086e7e}}</style>
<h1>Flamingo power rework</h1><p>Cheaper JLC06161H-3313 stackup: 1 oz outer copper, 0.5 oz inner copper. All components stay on top. The {preserve['unchangedPriorParts']} existing component positions and all {preserve['unchangedPriorRoutes']} existing routes are preserved.</p>
<p class="open"><b>The DC checks and the selected VDD load-change screen pass.</b> This does not establish hardware reliability. The controller, hot switch, contacts, ground return and retained extreme sensitivity cases still need work.</p>
<h2>12 V</h2><p>The added surface copper and stitching reduce the modeled loss at 5.5 A from 195.67 mV to <b>{loss:.2f} mV</b>, including the switch at its 25°C maximum resistance. At an 11.2 V input, the slot receives <b>{twelve['voltageFrom11p2VInput']:.5f} V</b>, above the 11.04 V floor by <b>{twelve['marginMV']:.2f} mV</b>. Doubling switch resistance leaves {twelve['marginAt2xFetResistanceSensitivityMV']:.2f} mV; that is a sensitivity, not a hot-resistance guarantee. Copper results include the existing mesh allowance and assume 80°C copper.</p>
<h2>VDD load changes</h2><p>Added two 330 µF reserve capacitors, each behind a 22 mΩ damping resistor. The direct ceramic bank remains 75.08 µF. The divider now uses 1.87 kΩ and 2.10 kΩ, both 0.1% / 10 ppm/K. Its nominal output is 1.13429 V. A 47 nF capacitor slows VDD startup.</p>
<p>For the retained 1.5 A ↔ 3 A example, the modeled range changes from about 1.083–1.185 V to <b>{low:.5f}–{high:.5f} V</b>, including voltage tolerance and conservative ripple alignment. The allowed range is 1.10–1.16 V. This example assumes a 200 ns edge, 0.5 µs delay, 5 nH supply link and 5 nH reserve branches. These are assumed inputs. It uses prescribed current catch-up, not a validated TPS62903 control-loop model. The separate damped branches were checked against ngspice.</p>
<p>The startup charge-current screen reaches {margins['startup']['peakCurrentAt3ALoadA']:.3f} A at the 3 A load, below the 4 A minimum peak current limit. All 18 prescribed normal-start timing cases pass; minimum modeled reset margin is {reset['normalStartupEnvelope']['minimumMarginMs']:.3f} ms.</p>
<img src="new-parts.png" alt="Two reserve capacitors and damping resistors on the top of the board">
<img src="power/first-response.png" alt="Conditional core-supply response for several assumed controller delays"><h2>Other supplies and checks</h2><table><tr><th>Path</th><th>Load</th><th>Conductor loss with allowance</th><th>Result</th></tr>{rows}</table>
<p>The shared 3.3 V screen and the bridge/flash/supervisor/pull-up screen pass. The doubled-FET-resistance sensitivity leaves {three['summary']['slotMarginWith2xFetResistanceSensitivityMV']:.3f} mV of slot margin. Full board geometry, connectivity, shorts, style and high-speed reference checks pass. 173 tests pass; 8 optional fixtures are skipped. Type checking and the datasheet audit pass. The existing C_VDD_28 orientation advisory is assessed against its actual pad-centred vertical connections.</p>
<h2>Cost</h2><p>The four reserve/damping parts and two precision divider parts total about $16 for two boards at the checked small-quantity distributor prices, plus the soft-start capacitors. This excludes shipping, sourcing/feeding charges and credits for the replaced resistors. The earlier quote is not an updated delivered price.</p>
<h2>Open checks</h2><ul>{issues}</ul>
<h2>Evidence</h2><p><a href="verified-final.circuit.json">Checked board</a> · <a href="review.json">Review and input hashes</a> · <a href="validation.json">Board validation</a> · <a href="slot-dc.json">Slot DC</a> · <a href="3v3-dc.json">Shared 3.3 V</a> · <a href="bridge-and-external-dc.json">Bridge and external loads</a> · <a href="core-dc.json">Core DC</a> · <a href="power/results.json">Ripple and load-change cases</a> · <a href="power/spice-check.json">Independent numerical check</a> · <a href="margins.json">Ratings and startup</a> · <a href="reset.json">Reset timing</a> · <a href="preservation.json">Preserved placement and routes</a></p>
<p>Design references: <a href="https://www.ti.com/lit/ds/symlink/tps62903.pdf">TI TPS62903</a>; <a href="https://search.kemet.com/download/specsheet/T520B337M2R5ATE009">KEMET reserve capacitor</a>; <a href="https://industrial.panasonic.com/cdbs/www-data/pdf/RDM0000/AOA0000C307.pdf">Panasonic divider resistors</a>; <a href="https://www.vishay.com/docs/30100/wsl.pdf">Vishay damping resistors</a>.</p><p><code>Board SHA-256: {digest}</code></p></html>''')
print(json.dumps(dict(slot12V=twelve,vddConditionalExample=conditional,corePlannedLoads=rails),indent=2))
